                  $cpv_now = $latest_snap ? (float)$latest_snap->cpv : 0;

                  // Compute decay velocity
                  $decay_status = "Data Awal";
                  $decay_class = "label-info";
                  if (count($snapshots) >= 2) {
                     $prev_snap = $snapshots[count($snapshots) - 2];
                     $diff_days = max(1, round((strtotime($latest_snap->snapshot_at) - strtotime($prev_snap->snapshot_at)) / 86400));
                     $velocity = round(($latest_snap->views - $prev_snap->views) / $diff_days);
                     if ($velocity > 5000) {
                        $decay_status = "Pertumbuhan Cepat (+" . number_format($velocity) . " views/hari)";
                        $decay_class = "label-success";
                     } elseif ($velocity > 500) {
                        $decay_status = "Stabil (+" . number_format($velocity) . " views/hari)";
                        $decay_class = "label-primary";
                     } else {
                        $decay_status = "Mulai Melandai / Saturasi (+" . number_format($velocity) . " views/hari)";
                        $decay_class = "label-warning";
                     }
                  }
