<!-- Include Chart.js -->
<script src="https://cdn.jsdelivr.net/npm/chart.js@3.9.1/dist/chart.min.js"></script>
<script>
document.addEventListener('DOMContentLoaded', function() {
   <?php if (!empty($snapshots)): ?>
      var labels = <?= json_encode(array_map(function($s) { return date('d M H:i', strtotime($s->snapshot_at)); }, $snapshots)); ?>;
      var dataViews = <?= json_encode(array_map(function($s) { return (int)$s->views; }, $snapshots)); ?>;
      var dataLikes = <?= json_encode(array_map(function($s) { return (int)$s->likes; }, $snapshots)); ?>;

      var ctx = document.getElementById('performanceDecayChart').getContext('2d');
      new Chart(ctx, {
         type: 'line',
         data: {
            labels: labels,
            datasets: [
               {
                  label: 'Total Views',
                  data: dataViews,
                  borderColor: '#0284c7',
                  backgroundColor: 'rgba(2, 132, 199, 0.1)',
                  fill: true,
                  tension: 0.3,
                  yAxisID: 'y'
               },
               {
                  label: 'Likes / Engagements',
                  data: dataLikes,
                  borderColor: '#10b981',
                  backgroundColor: 'transparent',
                  borderDash: [5, 5],
                  tension: 0.3,
                  yAxisID: 'y1'
               }
            ]
         },
         options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: {
               mode: 'index',
               intersect: false,
            },
            scales: {
               y: {
                  type: 'linear',
                  display: true,
                  position: 'left',
                  title: { display: true, text: 'Views' }
               },
               y1: {
                  type: 'linear',
                  display: true,
                  position: 'right',
                  grid: { drawOnChartArea: false },
                  title: { display: true, text: 'Likes' }
               }
            }
         }
      });
   <?php endif; ?>

   // Trigger Scrape Handler
   var csrfName = '<?= $this->security->get_csrf_token_name(); ?>';
   var csrfHash = '<?= $this->security->get_csrf_hash(); ?>';

   $(document).on('click', '.btn-trigger-scrape', function() {
      var id = $(this).data('id');
      var $btn = $(this);
      $btn.prop('disabled', true).html('<i class="fa fa-spinner fa-spin"></i> Sedang Men-scrape...');

      var postData = {};
      postData[csrfName] = csrfHash;

      $.ajax({
         url: BASE_URL + 'administrator/postings/trigger_scrape/' + id,
         type: 'POST',
         dataType: 'json',
         data: postData,
         success: function(res) {
            if (res.csrf_hash) csrfHash = res.csrf_hash;
            if (res.success) {
               if (typeof swal !== 'undefined') {
                  swal({
                     title: "Berhasil!",
                     text: res.message,
                     type: "success"
                  }, function() {
                     location.reload();
                  });
               } else {
                  alert(res.message);
                  location.reload();
               }
            } else {
               if (typeof swal !== 'undefined') {
                  swal("Gagal", res.message, "error");
               } else {
                  alert(res.message);
               }
               $btn.prop('disabled', false).html('<i class="fa fa-refresh"></i> Trigger Scrape Sekarang');
            }
         },
         error: function() {
            alert('Gagal menghubungi server untuk proses scraping.');
            $btn.prop('disabled', false).html('<i class="fa fa-refresh"></i> Trigger Scrape Sekarang');
         }
      });
   });
});
</script>
